// Backlog row statuses.
const (
	GameBacklogStatusBacklog    = "backlog"
	GameBacklogStatusInProgress = "in-progress"
	GameBacklogStatusFinished   = "finished"
	GameBacklogStatusDropped    = "dropped"
)

// gameBacklogTimeFormat is the RFC3339 UTC layout stamped into added_at and
// finished_at. Fixed-width and lexicographically sortable, so ORDER BY on
// the text columns is chronological.
const gameBacklogTimeFormat = time.RFC3339

// ValidGameBacklogStatus reports whether s is one of the four backlog statuses.
func ValidGameBacklogStatus(s string) bool {
	switch s {
	case GameBacklogStatusBacklog, GameBacklogStatusInProgress,
		GameBacklogStatusFinished, GameBacklogStatusDropped:
		return true
	}
	return false
}

