// migrateGameBacklog creates the game_backlog table and its indexes. Called
// from migrateExtras on every read-write store open; safe to re-run.
func (s *Store) migrateGameBacklog(ctx context.Context, conn *sql.Conn) error {
	if _, err := conn.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS game_backlog (
		rawg_id     INTEGER PRIMARY KEY,
		title       TEXT NOT NULL,
		slug        TEXT NOT NULL DEFAULT '',
		added_at    TEXT NOT NULL,
		status      TEXT NOT NULL DEFAULT 'backlog',
		hours       REAL NOT NULL DEFAULT 0,
		finished_at TEXT NOT NULL DEFAULT '',
		user_rating REAL NOT NULL DEFAULT 0,
		notes       TEXT NOT NULL DEFAULT ''
	)`); err != nil {
		return fmt.Errorf("game_backlog table migration failed: %w", err)
	}
	if _, err := conn.ExecContext(ctx, `CREATE INDEX IF NOT EXISTS idx_game_backlog_status ON game_backlog(status)`); err != nil {
		return fmt.Errorf("game_backlog status index migration failed: %w", err)
	}
	if _, err := conn.ExecContext(ctx, `CREATE INDEX IF NOT EXISTS idx_game_backlog_added_at ON game_backlog(added_at)`); err != nil {
		return fmt.Errorf("game_backlog added_at index migration failed: %w", err)
	}
	return nil
}

const gameBacklogSelectColumns = `SELECT rawg_id, title, slug, added_at, status, hours, finished_at, user_rating, notes FROM game_backlog`

