func (s *Store) SetGameBacklogStatus(ctx context.Context, rawgID int, status string) (GameBacklogRow, bool, error) {
	if !ValidGameBacklogStatus(status) {
		return GameBacklogRow{}, false, fmt.Errorf("set game_backlog status: unknown status %q", status)
	}

	s.lockForWrite()
	defer s.unlockAfterWrite()

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return GameBacklogRow{}, false, fmt.Errorf("set game_backlog status: %w", err)
	}
	defer tx.Rollback()

	existing, err := scanGameBacklogRow(tx.QueryRowContext(ctx,
		gameBacklogSelectColumns+` WHERE rawg_id = ?`, rawgID))
	if err == sql.ErrNoRows {
		return GameBacklogRow{}, false, nil
	}
	if err != nil {
		return GameBacklogRow{}, false, fmt.Errorf("set game_backlog status: %w", err)
	}
	finishedAt := gameBacklogFinishedAt(existing.Status, status, existing.FinishedAt)
	if _, err := tx.ExecContext(ctx,
		`UPDATE game_backlog SET status = ?, finished_at = ? WHERE rawg_id = ?`,
		status, finishedAt, rawgID); err != nil {
		return GameBacklogRow{}, false, fmt.Errorf("set game_backlog status: %w", err)
	}
	if err := tx.Commit(); err != nil {
		return GameBacklogRow{}, false, fmt.Errorf("set game_backlog status: %w", err)
	}
	existing.Status = status
	existing.FinishedAt = finishedAt
	return existing, true, nil
}

