const defaultGameBacklogListLimit = 500

// gameBacklogSortOrder whitelists sort keys to ORDER BY fragments; the input
// never reaches SQL otherwise.
func gameBacklogSortOrder(sort string) string {
	switch sort {
	case "title":
		return ` ORDER BY title COLLATE NOCASE ASC`
	case "hours":
		return ` ORDER BY hours DESC, added_at DESC`
	default: // "added"
		return ` ORDER BY added_at DESC`
	}
}

// ListGameBacklog returns rows per the filter. An empty result is a valid
// state ([]GameBacklogRow{}, nil), never nil.
func (s *Store) ListGameBacklog(ctx context.Context, f ListGameBacklogFilter) ([]GameBacklogRow, error) {
	if f.Status != "" && !ValidGameBacklogStatus(f.Status) {
		return nil, fmt.Errorf("list game_backlog: unknown status %q", f.Status)
	}
	limit := f.Limit
	if limit <= 0 {
		limit = defaultGameBacklogListLimit
	}

	query := gameBacklogSelectColumns + ` WHERE 1=1`
	var args []any
	if f.Status != "" {
		query += ` AND status = ?`
		args = append(args, f.Status)
	}
	query += gameBacklogSortOrder(f.Sort) + ` LIMIT ?`
	args = append(args, limit)

	rows, err := s.db.QueryContext(ctx, query, args...)
	if err != nil {
		return nil, fmt.Errorf("list game_backlog: %w", err)
	}
	defer rows.Close()
	out := []GameBacklogRow{}
	for rows.Next() {
		r, err := scanGameBacklogRow(rows)
		if err != nil {
			return nil, fmt.Errorf("scan game_backlog row: %w", err)
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// SearchGameBacklog returns rows whose title, slug, or notes contain query
// (case-insensitive substring), ranked title > slug > notes, then most
// recently added. status optionally filters first.
func (s *Store) SearchGameBacklog(ctx context.Context, query, status string, limit int) ([]GameBacklogRow, error) {
	q := strings.TrimSpace(query)
	if q == "" {
		return nil, fmt.Errorf("search game_backlog: query is required")
	}
	if status != "" && !ValidGameBacklogStatus(status) {
		return nil, fmt.Errorf("search game_backlog: unknown status %q", status)
	}
	if limit <= 0 {
		limit = defaultGameBacklogListLimit
	}

	// Escape LIKE wildcards in the user query so % and _ match literally.
	esc := strings.NewReplacer(`\`, `\\`, "%", `\%`, "_", `\_`)
	pattern := "%" + esc.Replace(q) + "%"

	querySQL := gameBacklogSelectColumns + ` WHERE 1=1`
	var args []any
	if status != "" {
		querySQL += ` AND status = ?`
		args = append(args, status)
	}
	querySQL += ` AND (
		title LIKE ? ESCAPE '\'
		OR slug LIKE ? ESCAPE '\'
		OR notes LIKE ? ESCAPE '\'
	)
	ORDER BY (CASE
		WHEN title LIKE ? ESCAPE '\' THEN 3
		WHEN slug LIKE ? ESCAPE '\' THEN 2
		WHEN notes LIKE ? ESCAPE '\' THEN 1
		ELSE 0 END) DESC, added_at DESC
	LIMIT ?`
	args = append(args, pattern, pattern, pattern, pattern, pattern, pattern, limit)

	rows, err := s.db.QueryContext(ctx, querySQL, args...)
	if err != nil {
		return nil, fmt.Errorf("search game_backlog: %w", err)
	}
	defer rows.Close()
	out := []GameBacklogRow{}
	for rows.Next() {
		r, err := scanGameBacklogRow(rows)
		if err != nil {
			return nil, fmt.Errorf("scan game_backlog row: %w", err)
		}
		out = append(out, r)
	}
	return out, rows.Err()
}
